// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        // Admissible domain: caller must be 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        // Restrict lengths to avoid "too many inputs" rejections
        vm.assume(_tos.length > 0 && _tos.length <= 10);
        vm.assume(v.length == _tos.length);
        // Bound each v[i] to a safe range to avoid overflow in multiplication
        for (uint i = 0; i < v.length; i++) {
            vm.assume(v[i] <= type(uint256).max / 1000000000000000000);
        }
        bool success;
        try c.transfer(_tos, v) returns (bool ret) {
            success = true;
            assertTrue(ret);
        } catch {
            success = false;
            // No assertion needed here; the rule applies only to non-reverting calls
        }
    }
}

